package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Canonical normalization for an owner's {@code address}. Whitespace is trimmed and every run of
 * whitespace collapsed to a single space, the text is upper-cased, and common abbreviations are
 * expanded on a whole-word basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
 * The transform is idempotent, so normalizing an already-normalized address returns it unchanged.
 *
 * <p>Applied whenever an owner is created (see {@link ValidateOwnerFields}) so the stored and returned
 * {@code address} is the normalized string, and reused wherever addresses are compared
 * (see {@link AssignHousehold}) so those comparisons see the same form.
 */
final class AddressNormalizer {

    private AddressNormalizer() {
    }

    static String normalize(String address) {
        if (address == null) {
            return "";
        }
        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(expand(tokens[i]));
        }
        return sb.toString();
    }

    private static String expand(String token) {
        switch (token) {
            case "ST":
                return "STREET";
            case "RD":
                return "ROAD";
            case "AVE":
                return "AVENUE";
            default:
                return token;
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}. Rejects a create request that is missing or blank in any
 * required field, so an invalid body is a 400 whose {@code errors} array names each offending field.
 * Runs before {@link BuildOwner}, which then reads the published body via {@code @Val}.
 *
 * <p>The {@code address} is normalized in place first (see {@link AddressNormalizer}) so it is stored
 * and returned in normalized form, and so the required-field check rejects an address that is blank
 * after normalization (for example one made only of whitespace).
 */
public class ValidateOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException {
        if (request.getAddress() != null) {
            request.setAddress(AddressNormalizer.normalize(request.getAddress()));
        }
        List<String> errors = new ArrayList<>();
        require(errors, "firstName", request.getFirstName());
        require(errors, "lastName", request.getLastName());
        require(errors, "address", request.getAddress());
        require(errors, "city", request.getCity());
        require(errors, "telephone", request.getTelephone());
        if (!errors.isEmpty()) {
            throw new MissingOwnerFieldsException(errors);
        }
        validated.set(request);
    }

    private static void require(List<String> errors, String field, String value) {
        if (value == null || value.isBlank()) {
            errors.add(field);
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.CityRegion;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Validates the owner's {@code postcode} WHEN PRESENT, so an owner created without a postcode stays
 * accepted (the request contract is backward-compatible). A supplied postcode must be exactly four
 * digits and, when the city has a known region, must fall within that region's fixed range
 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
 * postcode. Anything else is rejected with 400 via {@link InvalidPostcodeException}.
 *
 * <p>Reads the body published by the preceding validate step via {@code @Val}, so it runs before the
 * owner is built/loaded and an invalid postcode is a 400 rather than being masked by a later step.
 */
public class ValidateOwnerPostcode {

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return; // optional when absent
        }
        String city = request.getCity();
        if (!postcode.matches("[0-9]{4}")) {
            throw new InvalidPostcodeException(postcode, city, "must be exactly four digits");
        }
        int[] range = CityRegion.postcodeRange(city);
        if (range == null) {
            return; // no known region for this city; any 4-digit postcode is valid
        }
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidPostcodeException(postcode, city,
                    "out of range " + range[0] + "-" + range[1] + " for the city's region");
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Step of {@code POST /api/owners} that assigns the owner's deterministic {@code householdId}.
 *
 * <p>The identifier is the first 12 upper-case hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode} (last name trimmed, internal whitespace collapsed and
 * lower-cased). Because it is derived purely from the household key, every owner sharing the same
 * last name and postcode receives the SAME value automatically, regardless of creation order and
 * without scanning or back-filling other owners. An owner with no postcode has no household, so its
 * {@code householdId} is {@code null}.
 *
 * <p>Runs after {@link BuildOwner}, so it works on the built entity, and before
 * {@link EnsureUniqueIdentity}, so duplicate detection and {@link AssignHouseholdSize} see the
 * finalized value. Note {@code sharesHousehold} plays no part here: it only bypasses the duplicate
 * block downstream; the household link itself is always this computed value.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
    }

    /**
     * The deterministic householdId for a {@code (lastName, postcode)} pair, or {@code null} when the
     * postcode is absent (an owner with no postcode is not part of a household).
     */
    static String householdId(String lastName, String postcode) {
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        String key = normalize(lastName) + "|" + postcode.trim();
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

